'use strict';

const fs=require('fs');
const path=require('path');
const {chromium}=require('playwright');
const BASE='https://plan-ex.ru/erpv2/';
const OUT=path.resolve(process.env.P19_OUT||'P19_patch_b_runtime_output');
const SHOTS=path.join(OUT,'screenshots');
fs.mkdirSync(SHOTS,{recursive:true});
const VIEWPORTS=[{width:1920,height:1080},{width:1536,height:864},{width:1366,height:768}];
const U=p=>new URL(String(p).replace(/^\//,''),BASE).href;
const safe=e=>String(e&&(e.message||e)||'unknown').replace(/[A-Za-z0-9+/=]{24,}/g,'[REDACTED]').slice(0,900);
function creds(){const s=process.env.P19_CREDENTIALS_B64||'';if(!s)throw Error('credentials unavailable');return JSON.parse(Buffer.from(s,'base64').toString('utf8'));}
function cred(role){const x=creds().find(v=>String(v&&v.role||'').toUpperCase()===role);if(!x||!x.username||!x.password)throw Error(role+' credential unavailable');return x;}
async function newContext(browser,vp){return browser.newContext({viewport:vp,deviceScaleFactor:1,locale:'ru-RU',timezoneId:'Europe/Moscow',ignoreHTTPSErrors:false});}
async function login(browser,role,vp){const c=await newContext(browser,vp),p=await c.newPage(),x=cred(role);await p.goto(U('/login'),{waitUntil:'domcontentloaded',timeout:45000});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(x.username);await p.locator('input[type="password"]').first().fill(x.password);await Promise.all([p.waitForLoadState('domcontentloaded',{timeout:20000}).catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(350);if(/\/login(?:[/?#]|$)/i.test(p.url())){await c.close();throw Error(role+' login failed');}return{context:c,page:p};}
function diag(page){const d={consoleErrors:[],pageErrors:[],requestFailures:[],badResponses:[],assetFailures:[]};const oc=m=>{if(m.type()==='error')d.consoleErrors.push(m.text())};const oe=e=>d.pageErrors.push(String(e.message||e));const of=r=>{const x={method:r.method(),url:r.url(),resourceType:r.resourceType(),error:r.failure()?.errorText||'failed'};d.requestFailures.push(x);if(['stylesheet','script','font','image'].includes(x.resourceType))d.assetFailures.push(x)};const or=r=>{if(r.status()>=400){const x={status:r.status(),url:r.url(),resourceType:r.request().resourceType()};d.badResponses.push(x);if(['stylesheet','script','font','image'].includes(x.resourceType))d.assetFailures.push(x)}};page.on('console',oc);page.on('pageerror',oe);page.on('requestfailed',of);page.on('response',or);return{data:d,detach(){page.off('console',oc);page.off('pageerror',oe);page.off('requestfailed',of);page.off('response',or)}};}
async function overlayClosed(page,id){return page.locator(id).evaluate(el=>({open:el.classList.contains('is-open'),opacity:getComputedStyle(el).opacity,pointerEvents:getComputedStyle(el).pointerEvents})).then(x=>!x.open&&x.opacity==='0'&&x.pointerEvents==='none').catch(()=>false);}
async function baseMetrics(page){return page.evaluate(()=>{const h=document.documentElement;const links=[...document.querySelectorAll('link[rel="stylesheet"]')].map(x=>x.href);const root=getComputedStyle(h);return{scrollWidth:h.scrollWidth,clientWidth:h.clientWidth,horizontalOverflow:Math.max(0,h.scrollWidth-h.clientWidth),accent:root.getPropertyValue('--accent').trim().toLowerCase(),financeCss:links.find(x=>/finance-operation-actions\.css/i.test(x))||'',p16:links.some(x=>/p16-fullhd\.css/i.test(x)),p17:links.some(x=>/p17-corrections\.css/i.test(x)),green:/#0f766e|%230f766e|rgb\(15,\s*118,\s*110\)/i.test(document.head.innerHTML)};});}
async function modalMetrics(page,id,withLongProbe){return page.locator(id).evaluate((overlay,probe)=>{const modal=overlay.querySelector('.modal');const body=overlay.querySelector('.modal-body');const footer=overlay.querySelector('.finance-operation-footer');const card=overlay.querySelector('.finance-operation-card');const out={open:overlay.classList.contains('is-open'),overlayOpacity:getComputedStyle(overlay).opacity,overlayPointerEvents:getComputedStyle(overlay).pointerEvents,modal:null,body:null,footer:null,lastControl:null,disabledProbe:null,longProbe:false};if(!modal||!body)return out;const mr=modal.getBoundingClientRect(),br=body.getBoundingClientRect();out.modal={clientHeight:modal.clientHeight,scrollHeight:modal.scrollHeight,overflowY:getComputedStyle(modal).overflowY,top:mr.top,bottom:mr.bottom,height:mr.height};out.body={clientHeight:body.clientHeight,scrollHeight:body.scrollHeight,overflowY:getComputedStyle(body).overflowY,top:br.top,bottom:br.bottom,height:br.height};if(card){const b=document.createElement('button');b.type='button';b.disabled=true;b.textContent='P19 disabled probe';card.appendChild(b);const s=getComputedStyle(b);out.disabledProbe={opacity:s.opacity,cursor:s.cursor};b.remove();}let spacer=null;if(probe&&footer){spacer=document.createElement('div');spacer.setAttribute('data-p19-long-content','1');spacer.style.height='1200px';spacer.style.flex='0 0 1200px';spacer.style.pointerEvents='none';footer.parentNode.insertBefore(spacer,footer);body.scrollTop=body.scrollHeight;out.longProbe=true;}const br2=body.getBoundingClientRect();if(footer){const f=footer.getBoundingClientRect(),s=getComputedStyle(footer);out.footer={present:true,position:s.position,bottomProperty:s.bottom,top:f.top,bottom:f.bottom,withinBody:f.top>=br2.top-2&&f.bottom<=br2.bottom+2};}else out.footer={present:false};const controls=[...body.querySelectorAll('input,select,textarea,button')].filter(x=>x.getClientRects().length);if(controls.length){const el=controls[controls.length-1],r=el.getBoundingClientRect();out.lastControl={tag:el.tagName,text:(el.textContent||'').trim().slice(0,80),top:r.top,bottom:r.bottom,withinBody:r.top>=br2.top-2&&r.bottom<=br2.bottom+2};}out.body.clientHeight=body.clientHeight;out.body.scrollHeight=body.scrollHeight;out.body.scrollable=body.scrollHeight>body.clientHeight+2;out.modal.clientHeight=modal.clientHeight;out.modal.scrollHeight=modal.scrollHeight;out.modal.doubleScroll=modal.scrollHeight>modal.clientHeight+2&&['auto','scroll'].includes(getComputedStyle(modal).overflowY);if(spacer)spacer.remove();return out;},withLongProbe);}
function modalPass(m,requireFooter){if(!m||!m.open||!m.modal||!m.body)return false;const fits=m.modal.top>=20&&m.modal.bottom<=window.__P19_VH_PLUS_2;const bodyAuto=['auto','scroll'].includes(m.body.overflowY);const disabled=m.disabledProbe&&Number(m.disabledProbe.opacity)<=0.51&&m.disabledProbe.cursor==='not-allowed';const noDouble=!m.modal.doubleScroll;const scroll=m.longProbe?m.body.scrollable:true;const footer=requireFooter?m.footer&&m.footer.present&&m.footer.position==='sticky'&&m.footer.withinBody:true;return fits&&bodyAuto&&disabled&&noDouble&&scroll&&footer;}
async function ownerViewport(browser,vp,index){const s=await login(browser,'OWNER',vp),p=s.page,d=diag(p);const rec={viewport:`${vp.width}x${vp.height}`,status:'FAIL',list:null,view:null,allocation:null,cancel:null,diagnostics:null,error:null,screenshots:[]};try{let response=await p.goto(U('/company/finance/operations'),{waitUntil:'networkidle',timeout:50000});await p.waitForTimeout(200);const bm=await baseMetrics(p);const rows=p.locator('tr[data-operation-id]');const rowCount=await rows.count();rec.list={httpStatus:response?.status()??null,finalUrl:p.url(),rowCount,...bm};const listShot=`P19B_${index}_OWNER_list_${vp.width}x${vp.height}.png`;await p.screenshot({path:path.join(SHOTS,listShot),fullPage:false});rec.screenshots.push(`screenshots/${listShot}`);if(response?.status()!==200||rowCount<1||bm.horizontalOverflow>2||!bm.financeCss||bm.p16||bm.p17||bm.green||bm.accent!=='#7c4718')throw Error('operations list gate failed');let selected=false;for(let i=0;i<Math.min(rowCount,10);i++){await rows.nth(i).dblclick();await p.locator('#operation-view-modal.is-open').waitFor({state:'attached',timeout:10000});await p.locator('#operation-view-modal-body [data-operation-card]').waitFor({state:'attached',timeout:10000});await p.waitForTimeout(300);const allocate=p.locator('#operation-view-modal [data-operation-allocate-btn]').first();const cancel=p.locator('#operation-view-modal [data-operation-cancel-btn]').first();if(await allocate.count()&&!(await allocate.isDisabled())&&await cancel.count()){selected=true;break;}await p.locator('#operation-view-modal .modal-close').click();await p.waitForTimeout(180);}if(!selected)throw Error('no operation with enabled allocation/cancel action found');const viewShot=`P19B_${index}_OWNER_view_${vp.width}x${vp.height}.png`;await p.screenshot({path:path.join(SHOTS,viewShot),fullPage:false});rec.screenshots.push(`screenshots/${viewShot}`);const vm=await modalMetrics(p,'#operation-view-modal',true);const allocateBtn=await p.locator('#operation-view-modal [data-operation-allocate-btn]').first().evaluate(b=>({text:(b.textContent||'').trim(),disabled:b.disabled}));const cancelBtn=await p.locator('#operation-view-modal [data-operation-cancel-btn]').first().evaluate(b=>({text:(b.textContent||'').trim(),disabled:b.disabled}));rec.view={metrics:vm,allocateButton:allocateBtn,cancelButton:cancelBtn,pass:false};const viewPass=vm.open&&vm.body&&['auto','scroll'].includes(vm.body.overflowY)&&vm.body.scrollable&&!vm.modal.doubleScroll&&vm.footer?.present&&vm.footer.position==='sticky'&&vm.footer.withinBody&&vm.disabledProbe&&Number(vm.disabledProbe.opacity)<=.51&&vm.disabledProbe.cursor==='not-allowed'&&/Распределить/i.test(allocateBtn.text)&&!allocateBtn.disabled&&/Отменить операцию/i.test(cancelBtn.text);rec.view.pass=viewPass;if(!viewPass)throw Error('operation view modal layout/action gate failed');await p.locator('#operation-view-modal [data-operation-allocate-btn]').first().click();await p.locator('#operation-allocate-modal.is-open').waitFor({state:'attached',timeout:10000});await p.locator('#operation-allocate-modal-body [data-operation-allocation-form]').waitFor({state:'attached',timeout:10000});await p.waitForTimeout(250);const allocShot=`P19B_${index}_OWNER_allocate_${vp.width}x${vp.height}.png`;await p.screenshot({path:path.join(SHOTS,allocShot),fullPage:false});rec.screenshots.push(`screenshots/${allocShot}`);const am=await modalMetrics(p,'#operation-allocate-modal',true);const submit=await p.locator('#operation-allocate-modal button[type="submit"]').first().evaluate(b=>({text:(b.textContent||'').trim(),disabled:b.disabled})).catch(()=>null);rec.allocation={metrics:am,submitButton:submit,pass:false};const allocPass=am.open&&am.body&&['auto','scroll'].includes(am.body.overflowY)&&am.body.scrollable&&!am.modal.doubleScroll&&am.footer?.present&&am.footer.position==='sticky'&&am.footer.withinBody&&submit&&/Распределить/i.test(submit.text);rec.allocation.pass=allocPass;if(!allocPass)throw Error('allocation modal layout gate failed');await p.locator('#operation-allocate-modal .modal-close').click();await p.waitForTimeout(180);if(!(await overlayClosed(p,'#operation-allocate-modal')))throw Error('allocation modal did not close');await p.locator('#operation-view-modal [data-operation-cancel-btn]').first().click();await p.locator('#operation-cancel-modal.is-open').waitFor({state:'attached',timeout:5000});await p.waitForTimeout(150);const cancelShot=`P19B_${index}_OWNER_cancel_${vp.width}x${vp.height}.png`;await p.screenshot({path:path.join(SHOTS,cancelShot),fullPage:false});rec.screenshots.push(`screenshots/${cancelShot}`);const cancelForm=p.locator('#operation-cancel-modal .finance-cancel-form');const cancelSubmit=await cancelForm.locator('button[type="submit"]').first().evaluate(b=>({text:(b.textContent||'').trim(),disabled:b.disabled})).catch(()=>null);rec.cancel={open:await p.locator('#operation-cancel-modal').evaluate(x=>x.classList.contains('is-open')),formPresent:await cancelForm.count()>0,submitButton:cancelSubmit,pass:false};rec.cancel.pass=rec.cancel.open&&rec.cancel.formPresent;if(!rec.cancel.pass)throw Error('cancel modal open gate failed');await p.locator('#operation-cancel-modal .modal-close,[data-close-modal="operation-cancel-modal"]').first().click();await p.waitForTimeout(180);if(!(await overlayClosed(p,'#operation-cancel-modal')))throw Error('cancel modal did not close');await p.locator('#operation-view-modal .modal-close').click();await p.waitForTimeout(180);if(!(await overlayClosed(p,'#operation-view-modal')))throw Error('view modal did not close');rec.status='PASS';}catch(e){rec.error=safe(e);}finally{d.detach();rec.diagnostics=d.data;await s.context.close();}return rec;}
async function logistViewport(browser,vp,index){const s=await login(browser,'LOGIST',vp),p=s.page,d=diag(p);const rec={viewport:`${vp.width}x${vp.height}`,status:'FAIL',httpStatus:null,finalUrl:null,diagnostics:null,error:null,screenshot:null};try{const response=await p.goto(U('/company/finance/operations'),{waitUntil:'networkidle',timeout:45000});rec.httpStatus=response?.status()??null;rec.finalUrl=p.url();const shot=`P19B_${index}_LOGIST_forbidden_${vp.width}x${vp.height}.png`;await p.screenshot({path:path.join(SHOTS,shot),fullPage:false});rec.screenshot=`screenshots/${shot}`;const expected403=d.data.badResponses.filter(x=>x.status===403&&x.resourceType==='document'&&x.url.includes('/company/finance/operations'));const unexpectedHttp=d.data.badResponses.filter(x=>!expected403.includes(x));const unexpectedConsole=d.data.consoleErrors.filter(x=>!/status of 403|\b403\b/i.test(x));rec.status=rec.httpStatus===403&&unexpectedHttp.length===0&&unexpectedConsole.length===0&&d.data.pageErrors.length===0&&d.data.requestFailures.length===0&&d.data.assetFailures.length===0?'PASS':'FAIL';rec.expected403=expected403.length;rec.unexpectedHttp=unexpectedHttp;rec.unexpectedConsole=unexpectedConsole;}catch(e){rec.error=safe(e);}finally{d.detach();rec.diagnostics=d.data;await s.context.close();}return rec;}
(async()=>{const result={status:'FAIL',deployedSha:process.env.P19_DEPLOYED_SHA||null,owner:[],logist:[],seniorLogist:'NOT_TESTED_CREDENTIAL_UNAVAILABLE',summary:{},fatal:null};let browser;try{browser=await chromium.launch({headless:true});for(let i=0;i<VIEWPORTS.length;i++){const vp=VIEWPORTS[i];result.owner.push(await ownerViewport(browser,vp,i+1));result.logist.push(await logistViewport(browser,vp,i+1));}const ownerPass=result.owner.every(x=>x.status==='PASS'),logistPass=result.logist.every(x=>x.status==='PASS');const unexpectedConsole=result.owner.reduce((n,x)=>n+(x.diagnostics?.consoleErrors?.length||0),0)+result.logist.reduce((n,x)=>n+(x.unexpectedConsole?.length||0),0);const pageErrors=[...result.owner,...result.logist].reduce((n,x)=>n+(x.diagnostics?.pageErrors?.length||0),0);const requestFailures=[...result.owner,...result.logist].reduce((n,x)=>n+(x.diagnostics?.requestFailures?.length||0),0);const assetFailures=[...result.owner,...result.logist].reduce((n,x)=>n+(x.diagnostics?.assetFailures?.length||0),0);result.summary={ownerPass,logistPass,unexpectedConsole,pageErrors,requestFailures,assetFailures,viewports:VIEWPORTS.map(x=>`${x.width}x${x.height}`)};result.status=ownerPass&&logistPass&&unexpectedConsole===0&&pageErrors===0&&requestFailures===0&&assetFailures===0?'PASS':'FAIL';}catch(e){result.fatal=safe(e);}finally{if(browser)await browser.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P19_53_PATCH_B_RUNTIME_MATRIX.json'),JSON.stringify({owner:result.owner,logist:result.logist},null,2));fs.writeFileSync(path.join(OUT,'P19_54_PATCH_B_RUNTIME_SUMMARY.json'),JSON.stringify(result,null,2));console.log('P19_PATCH_B_RUNTIME='+result.status);process.exitCode=result.status==='PASS'?0:1;}})().catch(e=>{console.error(safe(e));process.exitCode=1;});
